def lpSummableRows (p : ℝ≥0∞) [Fact (1 ≤ p)] (F : ℕ → Y →L[𝕜] X) :
    Y →L[𝕜] lp (fun _ : ℕ => X) p :=
  ∑' j, (lp.singleContinuousLinearMap 𝕜 (fun _ : ℕ => X) p j).comp (F j)

